import {
    Table,
    GuidColumn,
    BooleanColumn,
    ListColumn,
    TranslatedTextColumn,
    ReferenceColumn,
} from '@servicenow/sdk/core'

export const sc_template = Table({
    allowWebServiceAccess: true,
    attributes: {
        domain_master: 'cat_item',
        update_synch: true,
    },
    display: 'name',
    extends: 'sys_metadata',
    label: 'Catalog Template',
    name: 'sc_template',
    schema: {
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        allow_edit_unlisted_variables: BooleanColumn({
            label: 'Allow edit of unlisted variables',
        }),
        available_for: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Available for',
            maxLength: 1024,
            referenceTable: 'user_criteria',
        }),
        short_description: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Short description',
            maxLength: 200,
        }),
        use_template_scope: BooleanColumn({
            label: 'Use template scope for creating records',
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        name: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Name',
            maxLength: 100,
        }),
        cat_item: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Catalog item',
            referenceTable: 'sc_cat_item',
            referenceQual: 'sys_class_name=sc_cat_item_composite_producer',
        }),
    },
})
